"""Explicit DAX for saved evidence. No causal estimation or recommendation logic."""
MEASURES={}
MEASURE_TABLE='CommercialMeasures'
def m(name,dax,fmt='#,##0.00',folder='Historical',description=''):
 MEASURES[name]={'dax':dax,'format':fmt,'folder':folder,'description':description or name}
GBP='£#,##0;−£#,##0;£0';PCT='0.00%;−0.00%;0.00%';PP='0.00" pp"';COUNT='#,##0'
m('Forward Evidence Current','SELECTEDVALUE(EvidenceStatus[forward_current], FALSE())','', 'Evidence')
m('Experiment Evidence Current','SELECTEDVALUE(EvidenceStatus[experiment_current], FALSE())','', 'Evidence')
m('Evidence Status','SELECTEDVALUE(EvidenceStatus[evidence_message])','', 'Evidence')
m('Snapshot Version','SELECTEDVALUE(EvidenceStatus[snapshot_id])','', 'Evidence')
m('Snapshot Stamp','"Validated snapshot " & SELECTEDVALUE(EvidenceStatus[snapshot_id]) & "  |  " & SELECTEDVALUE(EvidenceStatus[validation_utc]) & "  |  Native verification pending"','','Evidence')
m('Full Estate Scope','COUNTROWS(VALUES(DimGym[gym_id])) = COUNTROWS(ALL(DimGym))','', 'Evidence','Full saved estate scope only. A regional or arbitrary subset is unsupported for ranges.')
m('Uncertainty Scope','IF([Full Estate Scope], "Saved complete-estate conditional parameter range", IF(HASONEVALUE(DimGym[gym_id]), "Saved individual-gym conditional parameter range", "Range unavailable for selected gyms or region. Site interval endpoints cannot be added."))','', 'Evidence')
m('Historical Window','FORMAT(MIN(DimHistoryMonth[month]), "mmm yyyy") & "–" & FORMAT(MAX(DimHistoryMonth[month]), "mmm yyyy")','', 'Historical')
for name,col in [('Net Revenue','monthly_revenue'),('Subscription Revenue','subscription_revenue'),('Joining Fee Revenue','joining_fee_revenue'),('Ancillary Revenue','ancillary_revenue'),('Average Member Months','average_members'),('Opening Member Months','opening_members'),('Acquisitions','new_members'),('Opening-base Exits','opening_base_cancellations'),('Same-month Exits','same_month_cancellations'),('Qualified Prospects','qualified_prospects'),('Complaints','pricing_complaints'),('Marketing Spend','marketing_spend'),('Standard Subscription Revenue','standard_subscription_revenue'),('Standard Member Months','average_standard_members')]:
 m(name,f'SUM(FactHistory[{col}])',GBP if 'Revenue' in name or 'Spend' in name else COUNT)
for name,num,den,factor,fmt in [('ARPMM','Net Revenue','Average Member Months',1,'£0.00'),('Subscription Yield','Subscription Revenue','Average Member Months',1,'£0.00'),('Standard Yield','Standard Subscription Revenue','Standard Member Months',1,'£0.00'),('Opening-base Churn','Opening-base Exits','Opening Member Months',1,PCT),('Acquisition Rate','Acquisitions','Opening Member Months',1,PCT),('Qualified Conversion','Acquisitions','Qualified Prospects',1,PCT),('Complaints per 1000','Complaints','Average Member Months',1000,'0.00')]:
 m(name,f'DIVIDE([{num}], [{den}])'+(f' * {factor}' if factor!=1 else ''),fmt,description=f'{num} / {den}; summed numerator and exposure; missing or zero denominator is blank.')
m('Monthly Retention','IF(NOT ISBLANK([Opening-base Churn]), 1 - [Opening-base Churn])',PCT,description='One minus monthly exposure-weighted opening-base churn. This is not annual retention.')
m('Observed Months','DISTINCTCOUNT(FactHistory[month])',COUNT)
m('Average Members','DIVIDE([Average Member Months], [Observed Months])',COUNT)
m('Average Monthly Revenue','DIVIDE([Net Revenue], [Observed Months])',GBP)
m('Average Monthly Acquisitions','DIVIDE([Acquisitions], [Observed Months])',COUNT)
m('Closing Members','VAR LastMonth = MAX(FactHistory[month]) RETURN CALCULATE(SUM(FactHistory[closing_members]), KEEPFILTERS(FactHistory[month] = LastMonth))',COUNT,description='Stock at final observed month, never sum monthly membership stocks.')
m('Period Opening Members','VAR FirstMonth = MIN(FactHistory[month]) RETURN CALCULATE(SUM(FactHistory[opening_members]), KEEPFILTERS(FactHistory[month] = FirstMonth))',COUNT)
m('Period Member Growth','DIVIDE([Closing Members] - [Period Opening Members], [Period Opening Members])',PCT)
m('Average Occupancy','DIVIDE(SUMX(FactHistory, FactHistory[utilisation_pct] * FactHistory[opening_minutes]), SUM(FactHistory[opening_minutes]))',PCT)
m('Average Monthly Peak','AVERAGEX(VALUES(FactHistory[month]), CALCULATE(AVERAGE(FactHistory[peak_utilisation_pct])))',PCT)
m('Maximum Monthly Peak','MAX(FactHistory[peak_utilisation_pct])',PCT)
m('Promotion Frequency','DIVIDE(COALESCE(COUNTROWS(FILTER(FactHistory, FactHistory[promotion_active] = TRUE())), 0), COUNTROWS(FactHistory))',PCT)
for label,field in [('Standard','average_standard_members'),('Off-Peak','average_offpeak_members'),('Plus','average_premium_members')]:m(label+' Mix',f'DIVIDE(SUM(FactHistory[{field}]), [Average Member Months])',PCT)
prior='VAR MatchingMonths = SELECTCOLUMNS(VALUES(DimHistoryMonth[month]), "Month", EDATE(DimHistoryMonth[month], -12)) VAR PriorMonths = CALCULATE(DISTINCTCOUNT(FactHistory[month]), REMOVEFILTERS(DimHistoryMonth), TREATAS(MatchingMonths, DimHistoryMonth[month])) RETURN IF(PriorMonths = COUNTROWS(MatchingMonths), CALCULATE([{measure}], REMOVEFILTERS(DimHistoryMonth), TREATAS(MatchingMonths, DimHistoryMonth[month])))'
for name in ['Net Revenue','Closing Members','Average Members','Average Member Months','ARPMM','Acquisitions','Qualified Conversion','Opening-base Churn','Monthly Retention']:
 m(name+' Prior Year',prior.replace('{measure}',name),MEASURES[name]['format'],'Matching Period')
for name in ['Net Revenue','Closing Members','Average Members','Acquisitions','ARPMM']:
 m(name+' YoY',f'VAR Previous = [{name} Prior Year] RETURN IF(NOT ISBLANK(Previous) && Previous <> 0, DIVIDE([{name}] - Previous, Previous))',PCT,'Matching Period')
for name in ['Qualified Conversion','Opening-base Churn','Monthly Retention']:
 m(name+' Change pp',f'VAR Previous = [{name} Prior Year] RETURN IF(NOT ISBLANK(Previous) && NOT ISBLANK([{name}]), ([{name}] - Previous) * 100)',PP,'Matching Period')
for label,underlying,rate in [('Executive Revenue Comparison','Net Revenue YoY',False),('Executive Members Comparison','Closing Members YoY',False),('Executive ARPMM Comparison','ARPMM YoY',False),('Executive Acquisition Comparison','Acquisitions YoY',False),('Executive Churn Comparison','Opening-base Churn Change pp',True)]:
 display='"+0.00;−0.00;0.00"' if rate else '"+0.00%;−0.00%;0.00%"'
 suffix=' & " pp"' if rate else ''
 m(label,f'VAR Change = [{underlying}] RETURN IF(ISBLANK(Change), "Prior period unavailable", "vs " & FORMAT(MAX(DimHistoryMonth[year])-1,"0") & ": " & FORMAT(Change,{display}){suffix})','','Matching Period','Matching-period change for executive KPI. Percent growth; churn in percentage points; incomplete prior observations remain unavailable.')
for name in ['Net Revenue','Acquisitions','Qualified Conversion','Opening-base Churn']:
 m('Q4 '+name,f'CALCULATE([{name}], REMOVEFILTERS(DimHistoryMonth), DimHistoryMonth[year] = 2025, DimHistoryMonth[quarter] = "Q4")',MEASURES[name]['format'],'Q4 Context')
 m('Q4 '+name+' 2024',f'CALCULATE([{name}], REMOVEFILTERS(DimHistoryMonth), DimHistoryMonth[year] = 2024, DimHistoryMonth[quarter] = "Q4")',MEASURES[name]['format'],'Q4 Context')
 m('Q4 '+name+(' Change pp' if name in ['Qualified Conversion','Opening-base Churn'] else ' Growth'),f'VAR Previous = [Q4 {name} 2024] RETURN '+(f'IF(NOT ISBLANK(Previous), ([Q4 {name}] - Previous) * 100)' if name in ['Qualified Conversion','Opening-base Churn'] else f'DIVIDE([Q4 {name}] - Previous, Previous)'),PP if name in ['Qualified Conversion','Opening-base Churn'] else PCT,'Q4 Context')
m('Volume Bridge','IF(NOT ISBLANK([Net Revenue Prior Year]), ([Average Member Months] - [Average Member Months Prior Year]) * [ARPMM Prior Year])',GBP,'Historical Bridge')
m('ARPMM Bridge','IF(NOT ISBLANK([Net Revenue Prior Year]), [Average Member Months] * ([ARPMM] - [ARPMM Prior Year]))',GBP,'Historical Bridge','Interaction allocated to ARPMM. ARPMM includes tier mix, joining fees and ancillary revenue, not solely price.')
m('Revenue Bridge','SWITCH(SELECTEDVALUE(DimBridge[step]), "2024 revenue", [Net Revenue Prior Year], "Member volume", [Volume Bridge], "Total ARPMM", [ARPMM Bridge], "2025 revenue", [Net Revenue])',GBP,'Historical Bridge')
m('December Exit Run-rate','CALCULATE([Net Revenue], REMOVEFILTERS(DimHistoryMonth), DimHistoryMonth[month] = DATE(2025,12,1)) * 12',GBP,'Historical','Seasonal December revenue × 12. Neither earned annual revenue nor forecast.')
for label,field,fmt in [('Standard Headline December','current_standard_price','£0.00'),('Off-Peak Headline December','current_offpeak_price','£0.00'),('Plus Headline December','current_premium_price','£0.00'),('Competitor Recurring December','local_competitor_avg_price','£0.00'),('Competitor Gap December','competitor_price_gap','£0.00'),('Headroom Score','score','0.0'),('Saved Estate Rank','rank',COUNT),('December Competitor Count','competitor_count_3km',COUNT)]:
 m(label,f'SELECTEDVALUE(DimGym[{field}])',fmt,'December 2025 Snapshot','Saved December 2025 snapshot. VAT-inclusive GBP prices; ranks stay fixed under filters.')
for label,field in [('Headroom Band','band'),('Headroom Segment','segment')]:m(label,f'SELECTEDVALUE(DimGym[{field}])','','December 2025 Snapshot')
for label,field,fmt in [('Caution Count','caution_flag_count',COUNT),('Pricing Complaints 2025','complaints_per_1000_member_months_2025','0.00'),('Competitor Joining Fee December','competitor_mean_joining_fee_dec2025','£0.00'),('Competitor Intro Discount December','competitor_mean_first_month_discount_dec2025','£0.00'),('Rank Movement Sensitivity','max_absolute_rank_movement',COUNT)]:m(label,f'SELECTEDVALUE(FactHeadroom[{field}])',fmt,'December 2025 Snapshot')
m('Saved Recommendation','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[action]), "UNAVAILABLE — refresh evidence")','','Recommendations')
m('Recommended Increment','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[proposed_increment]))','£0','Recommendations')
m('Provisional Test Increment','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[provisional_test_increment]))','£0','Recommendations')
m('Recommendation Explanation','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[explanation]), [Evidence Status])','','Recommendations')
m('Recommendation Site Count','IF([Forward Evidence Current], COALESCE(COUNTROWS(FactRecommendation), 0))',COUNT,'Recommendations')
m('Conditional Raise Sites','IF([Forward Evidence Current], COALESCE(CALCULATE(COUNTROWS(FactRecommendation), FactRecommendation[action] IN {"RAISE £1", "RAISE £2"}), 0))',COUNT,'Recommendations')
m('Saved Policy Action','IF([Forward Evidence Current] && HASONEVALUE(DimPolicy[variant]), SELECTEDVALUE(FactPolicyRecommendation[action]))','','Recommendations')
m('Saved Policy Amount','IF([Forward Evidence Current] && HASONEVALUE(DimPolicy[variant]), SELECTEDVALUE(FactPolicyRecommendation[proposed_increment]))','£0','Recommendations')
for prefix in ['plus1','plus2']:
 for field in ['plausible','qualified','failed_gates','base_revenue','downside_revenue','downside_member_impact','revenue_lower','revenue_upper','post_competitor_gap','worst_sensitivity_revenue']:
  name=('£1' if prefix=='plus1' else '£2')+' '+field.replace('_',' ')
  m(name,f'IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[{prefix}_{field}]))',PCT if 'member_impact' in field else GBP if 'revenue' in field else '£0.00' if 'gap' in field else '', 'Qualification Evidence')
 label=('£1' if prefix=='plus1' else '£2')+' failed gates'
 m(label,f'IF([Forward Evidence Current] && HASONEVALUE(DimGym[gym_id]), IF(SELECTEDVALUE(FactRecommendation[{prefix}_complete]) = TRUE(), COALESCE(SELECTEDVALUE(FactRecommendation[{prefix}_failed_gates]), "None"), "Unavailable required evidence"))','','Qualification Evidence','Blank failed-gate source means no failures only when required evidence is complete. Missing evidence remains explicit.')
# Saved scenario combinations. Measures refuse multi-case/option sums.
scenario_guard='[Forward Evidence Current] && HASONEVALUE(DimCase[case]) && HASONEVALUE(DimPrice[price_increment])'
for name,col,fmt in [('Scenario Revenue','monthly_revenue',GBP),('Scenario Subscription','subscription_revenue',GBP),('Scenario Joining Fees','joining_fee_revenue',GBP),('Scenario Ancillary','ancillary_revenue',GBP),('Scenario Incremental Revenue','incremental_revenue',GBP),('Scenario December Members','month12_members',COUNT),('Scenario Member Difference','member_difference',COUNT),('Scenario Joins','new_members',COUNT),('Scenario Standard Joins','standard_joins',COUNT),('Scenario Prospects','qualified_prospects',COUNT),('Scenario Opening Exposure','opening_members',COUNT),('Scenario Average Exposure','average_members',COUNT),('Scenario Opening Exits','opening_base_cancellations',COUNT),('Scenario Incumbent Exposure','incumbent_standard_opening',COUNT),('Scenario Incumbent Exits','incumbent_standard_cancellations',COUNT),('Scenario Downgrades','incumbent_standard_downgrades',COUNT),('Scenario Exit Run-rate','annualised_exit_run_rate',GBP),('Scenario Standard Revenue','standard_subscription_revenue',GBP),('Scenario Standard Exposure','standard_average_members',COUNT)]:
 m(name,f'IF({scenario_guard}, SUM(FactScenarioAnnual[{col}]))',fmt,'Saved Scenarios')
for name,num,den,fmt in [('Scenario ARPMM','Scenario Revenue','Scenario Average Exposure','£0.00'),('Scenario Subscription Yield','Scenario Subscription','Scenario Average Exposure','£0.00'),('Scenario Standard Yield','Scenario Standard Revenue','Scenario Standard Exposure','£0.00'),('Scenario Conversion','Scenario Joins','Scenario Prospects',PCT),('Scenario Churn','Scenario Opening Exits','Scenario Opening Exposure',PCT),('Scenario Incumbent Churn','Scenario Incumbent Exits','Scenario Incumbent Exposure',PCT),('Scenario Downgrade Rate','Scenario Downgrades','Scenario Incumbent Exposure',PCT)]:m(name,f'DIVIDE([{num}], [{den}])',fmt,'Saved Scenarios')
m('Scenario Member Impact','DIVIDE([Scenario Member Difference], CALCULATE([Scenario December Members], REMOVEFILTERS(DimPrice), DimPrice[price_increment] = 0))',PCT,'Saved Scenarios')
for name,col,fmt in [('Scenario Monthly Revenue','monthly_revenue',GBP),('Scenario Monthly Closing','closing_members',COUNT),('Scenario Cumulative Increment','cumulative_incremental_revenue',GBP)]:
 m(name,f'IF({scenario_guard} && HASONEVALUE(DimScenarioMonth[month]), SUM(FactScenarioMonthly[{col}]))',fmt,'Saved Scenarios')
for end in ['lower','upper']:
 m('Scenario Increment '+end,f'IF({scenario_guard}, IF(HASONEVALUE(DimGym[gym_id]), SELECTEDVALUE(FactScenarioAnnual[incremental_revenue_{end}]), IF([Full Estate Scope], SELECTEDVALUE(FactScenarioEstate[incremental_revenue_{end}]))))',GBP,'Saved Uncertainty','Saved site or full-estate endpoint; never SUM. Blank for unsupported multi-gym or regional filters.')
 m('Scenario Members '+end,f'IF({scenario_guard}, IF(HASONEVALUE(DimGym[gym_id]), SELECTEDVALUE(FactScenarioAnnual[month12_members_{end}]), IF([Full Estate Scope], SELECTEDVALUE(FactScenarioEstate[month12_members_{end}]))))',COUNT,'Saved Uncertainty')
m('Positive Draw Fraction',f'IF({scenario_guard}, IF(HASONEVALUE(DimGym[gym_id]), SELECTEDVALUE(FactScenarioAnnual[positive_revenue_draw_fraction]), IF([Full Estate Scope], SELECTEDVALUE(FactScenarioEstate[positive_revenue_draw_fraction]))))',PCT,'Saved Uncertainty','Conditional parameter draws, excluding future shocks and transport uncertainty. Not a rollout probability.')
for name,col,fmt in [('Break-even Multiplier','break_even_response_multiplier','0.00'),('Break-even Member Impact','break_even_member_impact',PCT),('Break-even Crossings','break_even_crossings',COUNT),('Teaching Retention Ratio','teaching_break_even_retention',PCT)]:m(name,f'IF({scenario_guard} && HASONEVALUE(DimGym[gym_id]), SELECTEDVALUE(FactScenarioAnnual[{col}]))',fmt,'Break-even','Saved site stress test. Teaching ratio applies only to a uniformly affected subscription group; no estate stress root supplied.')
m('Scenario Selection Status','IF(NOT [Forward Evidence Current], [Evidence Status], IF(NOT HASONEVALUE(DimCase[case]), "Select one saved case. No forecasts are rerun.", "Jan–Dec 2026 saved scenarios. +£3 is an analytical comparison; Standard reaches unchanged Plus at 20 sites."))','','Saved Scenarios')
portfolio_guard='[Forward Evidence Current] && HASONEVALUE(DimPolicy[variant]) && HASONEVALUE(DimCase[case])'
for name,col,fmt in [('Portfolio Increment','incremental_revenue',GBP),('Portfolio Revenue','monthly_revenue',GBP),('Portfolio December Members','month12_members',COUNT),('Portfolio Member Difference','member_difference',COUNT),('Portfolio Joins','new_members',COUNT),('Portfolio Prospects','qualified_prospects',COUNT),('Portfolio Opening Exposure','opening_members',COUNT),('Portfolio Exits','opening_base_cancellations',COUNT),('Portfolio Average Exposure','average_members',COUNT),('Portfolio Subscription','subscription_revenue',GBP),('Portfolio Incumbent Exposure','incumbent_standard_opening',COUNT),('Portfolio Incumbent Exits','incumbent_standard_cancellations',COUNT),('Portfolio Downgrades','incumbent_standard_downgrades',COUNT)]:m(name,f'IF({portfolio_guard}, SUM(FactPortfolioSite[{col}]))',fmt,'Conditional Raise Portfolio')
for name,num,den,fmt in [('Portfolio Churn','Portfolio Exits','Portfolio Opening Exposure',PCT),('Portfolio Conversion','Portfolio Joins','Portfolio Prospects',PCT),('Portfolio ARPMM','Portfolio Revenue','Portfolio Average Exposure','£0.00'),('Portfolio Downgrade Rate','Portfolio Downgrades','Portfolio Incumbent Exposure',PCT)]:m(name,f'DIVIDE([{num}], [{den}])',fmt,'Conditional Raise Portfolio')
for end in ['lower','upper']:m('Portfolio Increment '+end,f'IF({portfolio_guard} && [Full Estate Scope], SELECTEDVALUE(FactPortfolio[incremental_revenue_{end}]))',GBP,'Saved Uncertainty','Complete named policy portfolio only. Regional and single-gym portfolio ranges suppressed; tests excluded.')
m('Portfolio Uncertainty Scope','IF([Full Estate Scope], "Saved full named policy portfolio range. TEST FIRST gains excluded.", "Portfolio range unavailable for selected gyms or region. Filtered points and weighted rates remain available.")','','Saved Uncertainty')
# Historical pilot inference ignores general historical-date and site filters explicitly.
for metric,label,fmt in [('controlled_acquisition_response','Historical Standard Acquisition Effect',PCT),('acquisition_elasticity','Historical Acquisition Elasticity','0.00'),('incumbent_churn_response_pp','Historical Incumbent Churn Effect',PP),('incumbent_downgrade_response_pp','Historical Downgrade Effect',PP),('conversion_response_pp','Historical Conversion Effect',PP)]:
 for suffix,col in [('', 'estimate'),(' lower','ci_lower'),(' upper','ci_upper')]:
  m(label+suffix,f'CALCULATE(SELECTEDVALUE(FactHistoricalEstimate[{col}]), REMOVEFILTERS(FactHistoricalEstimate), FactHistoricalEstimate[estimator] = "paired_equal", FactHistoricalEstimate[window] = "primary_6m", FactHistoricalEstimate[group] = "All assigned pairs", FactHistoricalEstimate[metric] = "{metric}")',fmt,'Historical £2 Pilot','Saved equal-pair estimate, all 12 pairs. October 2024–March 2025 versus April–September 2025. Local £2 policy evidence, not estate prediction.')
m('Historical Pilot Pairs','12',COUNT,'Historical £2 Pilot')
m('Historical Pilot Scope','"Saved £2 pilot: 12 pairs, Oct 2024–Mar 2025 vs Apr–Sep 2025. Independent of the displayed site/date filters."','','Historical £2 Pilot')
# Saved experiment population inference. General gym selection never recalculates inference.
eg='[Experiment Evidence Current] && HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimPopulation[population]) && HASONEVALUE(DimCheckpoint[checkpoint_months])'
for metric,label,fmt in [('revenue_effect','Experiment Revenue Effect',PCT),('incremental_revenue','Experiment Revenue Difference',GBP),('member_harm','Experiment Member Harm',PCT),('standard_acquisition_harm','Experiment Acquisition Harm',PCT),('incumbent_churn_change_pp','Experiment Churn Harm',PP),('incumbent_downgrade_change_pp','Experiment Downgrade Harm',PP),('complaints_change','Experiment Complaint Change','0.00')]:
 for suffix,col in [('', 'estimate'),(' lower','lower'),(' upper','upper')]:m(label+suffix,f'IF({eg}, CALCULATE(SELECTEDVALUE(FactExperimentEstimate[{col}]), FactExperimentEstimate[metric] = "{metric}"))',fmt,'Saved Experiment Inference')
m('Experiment One-sided p',f'IF({eg}, CALCULATE(SELECTEDVALUE(FactExperimentEstimate[p_value_one_sided]), FactExperimentEstimate[metric] = "revenue_effect"))','0.0000','Saved Experiment Inference')
m('Experiment Two-sided p',f'IF({eg}, CALCULATE(SELECTEDVALUE(FactExperimentEstimate[p_value_two_sided]), FactExperimentEstimate[metric] = "revenue_effect"))','0.0000','Saved Experiment Inference')
m('Experiment Complete Pairs',f'IF({eg}, CALCULATE(SELECTEDVALUE(FactExperimentEstimate[complete_pairs]), FactExperimentEstimate[metric] = "revenue_effect"))',COUNT,'Saved Experiment Inference')
m('Experiment Saved Decision',f'IF({eg}, SELECTEDVALUE(FactExperimentGovernance[decision], "DESCRIPTIVE — no saved governance classification for this population"), "UNAVAILABLE — select current saved evidence")','','Saved Experiment Inference')
m('Experiment Required Response','SWITCH([Experiment Saved Decision], "EXTEND TEST", "Keep controls and collect further complete evidence. Early reviews cannot authorise rollout.", "STOP", "Stop the tested policy and investigate controlled harm.", "MODIFY", "Investigate service pressure or inconclusive harm; revise and retain controls.", "ROLL OUT", "Conditional £1 progression for comparable first-repricing sites only; retain controls.", "Authoritative conclusion unavailable.")','','Saved Experiment Inference')
m('Experiment Interval Status',f'IF({eg}, CALCULATE(SELECTEDVALUE(FactExperimentEstimate[interval_status]), FactExperimentEstimate[metric] = "revenue_effect"))','','Saved Experiment Inference')
m('Experiment Window','VAR Checkpoint = SELECTEDVALUE(DimCheckpoint[checkpoint_months],6) RETURN FORMAT(EDATE(DATE(2026,1,1),-Checkpoint), "mmm yyyy") & "–Dec 2025 vs Jan–" & FORMAT(DATE(2026, Checkpoint,1),"mmm") & " 2026. " & SELECTEDVALUE(DimSimulation[simulation],"select one simulation") & "; " & SELECTEDVALUE(DimPopulation[population],"select one population")','','Saved Experiment Inference')
# Profiles filter paths by saved population through dimensional attributes; no bidirectional bridge.
popfilter='FILTER(ALL(DimGym), SWITCH(TRUE(), SELECTEDVALUE(DimPopulation[population]) = "All assigned pairs", DimGym[experiment_assignment] IN {"Treatment", "Control"}, SELECTEDVALUE(DimPopulation[population]) = "First repricing", DimGym[experiment_population] = "First repricing", SELECTEDVALUE(DimPopulation[population]) = "Repeat repricing", DimGym[experiment_population] = "Repeat repricing", LEFT(SELECTEDVALUE(DimPopulation[population]),7) = "Region:", DimGym[region] = TRIM(MID(SELECTEDVALUE(DimPopulation[population]),8,100)) && DimGym[experiment_assignment] IN {"Treatment", "Control"}, FALSE()))'
for label,col,fmt in [('Revenue','monthly_revenue',GBP),('Subscription','subscription_revenue',GBP),('Joining Fees','joining_fee_revenue',GBP),('Ancillary','ancillary_revenue',GBP),('Average Exposure','average_members',COUNT),('Opening Exposure','opening_members',COUNT),('Joins','new_members',COUNT),('Standard Joins','standard_joins',COUNT),('Prospects','qualified_prospects',COUNT),('Incumbent Exposure','incumbent_standard_opening',COUNT),('Incumbent Exits','incumbent_standard_cancellations',COUNT),('Downgrades','incumbent_standard_downgrades',COUNT),('Complaints','pricing_complaints',COUNT),('Standard Exposure','standard_average_members',COUNT),('Standard Revenue','standard_subscription_revenue',GBP),('Paid Rate Numerator','incumbent_paid_rate_numerator',GBP),('Protected Exposure','incumbent_protected_opening',COUNT),('Repriced Exposure','incumbent_repriced_opening',COUNT)]:
 dax=f'VAR Checkpoint = SELECTEDVALUE(DimCheckpoint[checkpoint_months],6) RETURN IF(HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimPopulation[population]), CALCULATE(SUM(FactExperimentPath[{col}]), {popfilter}, KEEPFILTERS(DimExperimentMonth[month_number] <= Checkpoint)))'
 m('Experiment Path '+label,dax,fmt,'Experiment Profiles')
for name,num,den,fmt,factor in [('Conversion','Joins','Prospects',PCT,1),('Churn','Incumbent Exits','Incumbent Exposure',PCT,1),('Downgrade Rate','Downgrades','Incumbent Exposure',PCT,1),('ARPMM','Revenue','Average Exposure','£0.00',1),('Subscription Yield','Subscription','Average Exposure','£0.00',1),('Standard Yield','Standard Revenue','Standard Exposure','£0.00',1),('Complaints per 1000','Complaints','Average Exposure','0.00',1000),('Paid Rate','Paid Rate Numerator','Incumbent Exposure','£0.00',1),('Protected Share','Protected Exposure','Incumbent Exposure',PCT,1),('Repriced Share','Repriced Exposure','Incumbent Exposure',PCT,1)]:m('Experiment Path '+name,f'DIVIDE([Experiment Path {num}], [Experiment Path {den}]) * {factor}',fmt,'Experiment Profiles')
m('Experiment Path Closing',f'VAR Checkpoint = SELECTEDVALUE(DimCheckpoint[checkpoint_months],6) VAR LastMonth = CALCULATE(MAX(FactExperimentPath[month]), KEEPFILTERS(DimExperimentMonth[month_number] <= Checkpoint)) RETURN IF(HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimPopulation[population]), CALCULATE(SUM(FactExperimentPath[closing_members]), FactExperimentPath[month] = LastMonth, {popfilter}, KEEPFILTERS(DimExperimentMonth[month_number] <= Checkpoint)))',COUNT,'Experiment Profiles')
for fact,label in [('FactExperimentMonitoring','Monitoring'),('FactExperimentPair','Pair')]:
 m('Experiment '+label+' In Population',f'VAR Population = SELECTEDVALUE(DimPopulation[population]) VAR RowPopulation = SELECTEDVALUE({fact}[population]) RETURN IF(Population = "All assigned pairs" || Population = RowPopulation, 1, IF(LEFT(Population,7) = "Region:", IF('+ (f'LOOKUPVALUE(DimGym[region], DimGym[gym_id], SELECTEDVALUE({fact}[gym_id]))' if label=='Monitoring' else f'SELECTEDVALUE({fact}[region])')+' = TRIM(MID(Population,8,100)), 1, 0), 0))','0','Experiment Profiles')
m('Recommended Standard Price','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[proposed_standard_price]))','£0.00','Recommendations')
m('Provisional Test Price','IF([Forward Evidence Current], SELECTEDVALUE(FactRecommendation[provisional_test_price]))','£0.00','Recommendations')
m('Gyms In Selection','COUNTROWS(VALUES(DimGym[gym_id]))',COUNT,'December 2025 Snapshot')
m('Median Standard Price','MEDIAN(DimGym[current_standard_price])','£0.00','December 2025 Snapshot')
m('Average Competitor Gap','AVERAGE(DimGym[competitor_price_gap])','£0.00','December 2025 Snapshot','Unweighted mean of saved site recurring gaps; VAT-inclusive GBP.')
m('Caution Sites','COALESCE(COUNTROWS(FILTER(DimGym, DimGym[caution_flag_count] > 0)), 0)',COUNT,'December 2025 Snapshot')
m('Headroom Churn 2025','SELECTEDVALUE(FactHeadroom[churn_rate_2025])',PCT,'December 2025 Snapshot')
m('Headroom Peak 2025','SELECTEDVALUE(FactHeadroom[average_monthly_peak_2025])',PCT,'December 2025 Snapshot')
for label,field in [('Point','estimate'),('Lower','lower'),('Upper','upper'),('Tolerance','tolerance')]:
 m('Guardrail '+label,f'IF({eg}, SELECTEDVALUE(FactExperimentGuardrail[{field}]))','0.00','Saved Experiment Inference')
 m('Guardrail '+label+' Display',f'VAR DisplayAmount = [Guardrail {label}] RETURN IF(NOT ISBLANK(DisplayAmount), IF(CONTAINSSTRING(SELECTEDVALUE(FactExperimentGuardrail[metric]), "_pp"), FORMAT(DisplayAmount,"0.00") & " pp", FORMAT(DisplayAmount,"0.00%")), "Unavailable")','','Saved Experiment Inference')
m('Guardrail Upper Pass',f'IF({eg}, IF(ISBLANK([Guardrail Upper]), "Uncertainty unavailable", IF([Guardrail Upper] <= [Guardrail Tolerance], "PASS", "Upper bound exceeds limit")))','','Saved Experiment Inference')
m('Experiment Pair Revenue Effect','VAR LogEffect = SELECTEDVALUE(FactExperimentPair[revenue_log]) RETURN IF([Experiment Evidence Current] && HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimCheckpoint[checkpoint_months]) && NOT ISBLANK(LogEffect), EXP(LogEffect) - 1)',PCT,'Saved Experiment Inference')
METRIC_PANELS={
 'Executive Portfolio':['Conditional Raise Sites','Portfolio Increment','Portfolio Member Difference','Portfolio Increment lower','Portfolio Increment upper'],
 'Historical Pilot':['Historical Standard Acquisition Effect','Historical Standard Acquisition Effect lower','Historical Standard Acquisition Effect upper','Historical Acquisition Elasticity','Historical Incumbent Churn Effect','Historical Incumbent Churn Effect lower','Historical Incumbent Churn Effect upper','Historical Downgrade Effect','Historical Downgrade Effect lower','Historical Downgrade Effect upper'],
 'Q4 and Mix':['Q4 Net Revenue Growth','Q4 Acquisitions Growth','Q4 Opening-base Churn Change pp','Q4 Qualified Conversion Change pp','Standard Mix','Off-Peak Mix','Plus Mix','Marketing Spend'],
 'Detail Position':['Standard Headline December','Competitor Recurring December','Competitor Gap December','Headroom Band','Saved Estate Rank','Caution Count','Rank Movement Sensitivity'],
 'Detail Qualification £1':['£1 plausible','£1 qualified','£1 base revenue','£1 downside revenue','£1 downside member impact','£1 revenue lower','£1 failed gates'],
 'Detail Qualification £2':['£2 plausible','£2 qualified','£2 base revenue','£2 downside revenue','£2 downside member impact','£2 revenue lower','£2 failed gates']}
expressions=[]
for name in dict.fromkeys(n for panel in METRIC_PANELS.values() for n in panel):
 f=MEASURES[name]['format']
 if name.endswith(' plausible') or name.endswith(' qualified'):value=f'IF(ISBLANK([{name}]), "Unavailable", IF([{name}], "Yes", "No"))'
 elif f:value=f'IF(ISBLANK([{name}]), "Unavailable", FORMAT([{name}], "{f.replace(chr(34),chr(34)*2)}"))'
 else:value=f'IF(ISBLANK([{name}]), "Unavailable", [{name}] & "")'
 expressions.extend(['"'+name+'"',value])
m('Metric Panel Saved Value','SWITCH(SELECTEDVALUE(DimMetricPanel[metric]), '+', '.join(expressions)+', "Unavailable")','','Metric Definitions','Presentation of existing explicit measures; source numeric measures remain available and unrounded.')
for name,target,fmt in [('Base Portfolio Increment','Portfolio Increment',GBP),('Base Portfolio Member Difference','Portfolio Member Difference',COUNT),('Base Portfolio Increment lower','Portfolio Increment lower',GBP)]:m(name,f'CALCULATE([{target}], REMOVEFILTERS(DimPolicy), DimPolicy[variant] = "base")',fmt,'Conditional Raise Portfolio')
for label,action in [('Saved Policy Raise £1 Sites','RAISE £1'),('Saved Policy Raise £2 Sites','RAISE £2'),('Saved Policy Test Sites','TEST FIRST')]:m(label,f'IF([Forward Evidence Current] && HASONEVALUE(DimPolicy[variant]), COALESCE(CALCULATE(COUNTROWS(FactPolicyRecommendation), FactPolicyRecommendation[action] = "{action}"), 0))',COUNT,'Recommendations')
m('Historical Reporting Note','"Historical window: " & [Historical Window] & ". Prior year uses the same months; incomplete comparisons are unavailable. Pricing snapshots are December 2025; conditional portfolio is Jan–Dec 2026."','','Historical')
for label,col,fmt in [('Revenue','monthly_revenue',GBP),('Incumbent Exposure','incumbent_standard_opening',COUNT),('Incumbent Exits','incumbent_standard_cancellations',COUNT),('Downgrades','incumbent_standard_downgrades',COUNT)]:
 m('Experiment Profile '+label,f'VAR Checkpoint = SELECTEDVALUE(DimCheckpoint[checkpoint_months],6) VAR Month = SELECTEDVALUE(DimExperimentMonth[month]) VAR PreStart = EDATE(DATE(2026,1,1),-Checkpoint) RETURN IF([Experiment Evidence Current] && HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimPopulation[population]) && NOT ISBLANK(Month), IF(Month >= PreStart && Month < DATE(2026,1,1), CALCULATE(SUM(FactExperimentHistory[{col}]), {popfilter}), IF(Month >= DATE(2026,1,1) && Month <= DATE(2026,Checkpoint,1), CALCULATE(SUM(FactExperimentPath[{col}]), {popfilter}))))',fmt,'Experiment Profiles','Common deduplicated pre-period actuals plus one saved simulated post path, for matching-length windows.')
m('Experiment Profile Closing',f'VAR Checkpoint = SELECTEDVALUE(DimCheckpoint[checkpoint_months],6) VAR Month = SELECTEDVALUE(DimExperimentMonth[month]) VAR PreStart = EDATE(DATE(2026,1,1),-Checkpoint) RETURN IF([Experiment Evidence Current] && HASONEVALUE(DimSimulation[simulation]) && HASONEVALUE(DimPopulation[population]) && NOT ISBLANK(Month), IF(Month >= PreStart && Month < DATE(2026,1,1), CALCULATE(SUM(FactExperimentHistory[closing_members]), {popfilter}), IF(Month >= DATE(2026,1,1) && Month <= DATE(2026,Checkpoint,1), CALCULATE(SUM(FactExperimentPath[closing_members]), {popfilter}))))',COUNT,'Experiment Profiles','A stock at one axis month. Common history is counted once, never repeated across simulations.')
